    sections: [
      { id: 'structure', navigationLabel: 'Structure', title: 'The website structure', paragraphs: ['The sitemap brings the website structure into view: document solutions, company information, client stories and contact, alongside dedicated print audit and offer forms.', 'It also distinguishes planned additions from the main structure and identifies campaign landing pages as separate destinations.'], visual: 'Website sitemap', image: 'mds-sitemap', caption: 'The sitemap, including the solution pages, enquiry paths and separately marked future scope.' },
      { id: 'interface', navigationLabel: 'Interface', title: 'The homepage', paragraphs: ['The homepage set the tone for the whole site: a bold orange header, a carousel of print statistics and a clear route into the document solutions offer.', 'The design was responsive from the start, with the same content and structure adapting to mobile screens.'], visual: 'Desktop and mobile homepages', image: 'mds-home-comparison', caption: 'The full homepage and its mobile adaptation.' },
      { title: 'Six benefits, six colours', paragraphs: ['The Document Solutions overview introduced six benefits, each with its own colour and icon. Each benefit opened into a full page with expandable sections, keeping long content manageable.'], visual: 'Document Solutions overview', images: ['mds-document-solutions'], imageLayout: 'gallery', caption: 'The overview page with the six colour-coded benefits.' },
      { title: 'The solution pages', paragraphs: ['Each solution page carried its colour through the header, sidebar and icons, so visitors always knew where they were in the site.'], visual: 'Solution pages', images: ['mds-optimise', 'mds-security', 'mds-print-budget', 'mds-efficiency', 'mds-control'], imageLayout: 'gallery', caption: 'Optimise Document Processes, Improve Your Security, Reduce Your Print Budget, Increase Efficiency and Gain Complete Control.' },
      { title: 'About and Why QuoStar', paragraphs: ['The supporting pages leaned on illustration: a paper boat for About Us, and a series of full-width coloured panels with paper craft artwork for Why QuoStar.'], visual: 'About and Why QuoStar', images: ['mds-about', 'mds-why-quostar'], imageLayout: 'gallery', caption: 'About Us and the Why QuoStar page.' },
      { title: 'Client stories', paragraphs: ['A case studies section gave the offer credibility, with an index page and full client stories that ended in a clear list of results.'], visual: 'Case studies', images: ['mds-case-studies', 'mds-case-study-story'], imageLayout: 'gallery', caption: 'The case studies index and a client story for ASM Assembly Systems.' },
      { id: 'enquiries', title: 'From visit to enquiry', paragraphs: ['Every page led towards an enquiry: the contact page, a complimentary print audit registration form, and the MDS Challenge free trial sign-up, each closing with a thank you page and follow-up actions.'], visual: 'Enquiry journey', images: ['mds-contact', 'mds-print-audit', 'mds-offer', 'mds-thanks'], imageLayout: 'gallery', caption: 'Contact, the print audit form, the free trial offer and the thank you page.' },
      { title: 'Campaign landing page', paragraphs: ['A standalone campaign landing page gave marketing activity a focused destination, built from the same visual language as the main site.'], visual: 'Campaign landing page', images: ['mds-campaign'], imageLayout: 'gallery', caption: 'The campaign landing page for business critical print and document control.' },
    ], contribution: '', outcomes: [],
