const workOrder: Project['slug'][] = ['secure-code-warrior', 'origin-markets', 'origin-design-system', 'mendeley', 'aladdin', 'corresilience', 'pawsquad', 'mds-quostar', 'migreat', 'meliniki', 'jobme'];
export const projectsByYear: Project[] = workOrder.map(getProject);
export const projectTags = ['Research', 'Product Design', 'Product Identity', 'Brand', 'Accessibility', 'Vision', 'Design Systems', 'Prototyping', 'AI-assisted Prototyping', 'Web Design', 'Front-end Development', 'Logo Design', 'Illustration', 'Label Design'];
export function projectSectionLabels(project: Project): string[] {
  return ['Overview', ...new Set(project.sections.flatMap(section => section.navigationLabel ? [section.navigationLabel] : [])), ...(project.outcomes.length ? ['Outcomes'] : [])];
}
export function projectWorkAreas(project: Project): string[] {
  if (project.workAreas) return project.workAreas;
  const sectionOnly = ['Overview', 'Outcomes', 'Challenge', 'Structure', 'Brief'];
  return [...new Set([...projectSectionLabels(project)
    .filter(label => !sectionOnly.includes(label))
    .map(label => ['Label design', 'Logo'].includes(label) ? 'Illustration' : label === 'Products' ? 'Interface' : label),
    ...(project.tags.includes('Accessibility') ? ['Accessibility'] : [])])];
}
export const projectFilters = [...new Set(projectsByYear.flatMap(projectWorkAreas))];
export function projectMatchesFilter(project: Project, filter: string) {
  return projectFilters.includes(filter) && (project.slug === 'secure-code-warrior' || projectWorkAreas(project).includes(filter));
}
export function pageMeta(title: string, description: string, type: 'website' | 'article' = 'website') {
  return { title: `${title} · Rachel Kirmitsaki`, description, ogType: type } as const;
}

export function getProject(slug: Project['slug']): Project {
  const project = projects.find(item => item.slug === slug);
  if (!project) throw new Error(`Missing portfolio project: ${slug}`);
  return project;
}

export function caseStudyMeta(project: Project) {
  return pageMeta(`${project.name} · Case Study`, project.summary, 'article');
}
